var a=[{title:`Il quadro generale`,text:`L’esercizio consuma energia, e il cibo fornisce ciò che ti serve per allenarti, recuperare e costruire tessuto. Una dieta varia di solito comprende alimenti proteici, alimenti ricchi di carboidrati, frutta, verdura e fonti di grassi. Un’alimentazione molto restrittiva può frenare prestazioni e recupero anche quando gli allenamenti sono ben progettati.`},{title:`Proteine e muscoli`,text:`Le proteine forniscono amminoacidi che il corpo usa per mantenere i tessuti e adattare il muscolo. La ricerca sugli adulti che si allenano cita spesso circa 1,4–2,0 grammi di proteine per chilogrammo di massa corporea al giorno come intervallo basato sulle evidenze. I bisogni differiscono con età, allenamento e circostanze personali, e non devi calcolare questo numero.`},{title:`Carboidrati e grassi`,text:`I carboidrati alimentano sforzi duri ripetuti e sessioni di resistenza mantenendo il glicogeno muscolare. I grassi alimentari forniscono acidi grassi essenziali e aiutano ad assorbire certe vitamine. Le strategie dettagliate di nutrizione sportiva contano di più man mano che sale il volume di allenamento. Da principiante, concentrati prima su pasti regolari ed equilibrati.`},{title:`Esempio`,text:`Se fai allenamento di forza tre giorni a settimana, potresti costruire i pasti attorno a legumi, pesce, uova o un’altra fonte di proteine, aggiungere cereali o patate per l’energia e includere verdura e frutta. Ciò che mangi nell’arco della settimana conta più che bere un particolare frullato subito dopo ogni serie.`},{title:`Quando chiedere aiuto a un esperto`,text:`Se hai una condizione medica, preoccupazioni sull’alimentazione o un obiettivo di prestazione specializzato, parla con un dietista registrato o con un professionista sanitario. TrainUp non fornisce obiettivi calorici individuali, monitoraggio dei macronutrienti né piani alimentari per dimagrire.`}];var o=[{label:`Position stand ISSN: proteine ed esercizio`,url:`https://pmc.ncbi.nlm.nih.gov/articles/PMC5477153/`},{label:`Position stand ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var t={sections:a,sources:o};export{t as default,a as sections,o as sources};